import { Box } from '@mui/material';
import { Link } from 'react-scroll';
import { useTranslation } from 'react-i18next';
import { useEffect, useRef, useState } from 'react';
import clsx from 'clsx';

// Icons
// import { faBars } from '@fortawesome/free-solid-svg-icons';

// Components
import Intro from '../../../modules/Intro/Intro';
import AboutMe from '../../../modules/AboutMe/AboutMe';
import ScrollLink from '../../components/ScrollLink/ScrollLink';
import LanguageSwitcher from '../../components/LanguageSwitcher/LanguageSwitcher';
import Skill from '../../../modules/Skill/Skill';
import Archive from '../../../modules/Archive/Archive';
// import Career from '../../../modules/Career/Career';
import Project from '../../../modules/Project/Project';

//Hooks
import { useBreakpoints } from '../../hooks/use-breakpoints.hook';

// Styles
import styles from './MainPage.module.scss';
import Career from '../../../modules/Career/Career';

type MainPageProps = {
  bgColor?: string;
};

const MainPage = (props: MainPageProps) => {
  const { t } = useTranslation();
  const { smUp } = useBreakpoints();

  const [showIcons, setShowIcons] = useState<boolean>(true);

  const mainPage = useRef<null | HTMLDivElement>(null);

  // Scroll to Top on mount
  useEffect(() => {
    setTimeout(() => {
      mainPage.current && mainPage.current.scrollIntoView();
    }, 300);
  }, []);

  return (
    <Box className={styles['main-page']} ref={mainPage}>
      {/* Header */}
      <Box className={styles['header']}>
        <Box className={styles['header-content']}>
          <>
            <Box
              className={styles['header-title']}
              sx={{
                color: 'app.brown',
                // fontSize: '1.75rem',
                fontWeight: '600',
                fontFamily: 'Montserrat',
              }}
            >
              <Link to='intro' spy={true} offset={-100}>
                {t('app.title')}
              </Link>
              {/* {!smUp && (
                <Box
                  className={styles['header-content-bar']}
                  onClick={() => setShowIcons(!showIcons)}
                >
                  <FontAwesomeIcon
                    icon={faBars}
                    style={{
                      color: '#444444',
                    }}
                  />
                </Box>
              )} */}
            </Box>
          </>
          <>
            {(smUp || showIcons) && (
              <Box
                className={clsx(
                  styles['header-content-icons']
                  // , styles['show']
                )}
              >
                <ScrollLink to='AboutMe'>{t('app.nav.aboutMe')}</ScrollLink>
                <ScrollLink to='Career'>{t('app.nav.career')}</ScrollLink>
                <ScrollLink to='skill'>{t('app.nav.skills')}</ScrollLink>
                <ScrollLink to='Archive'>{t('app.nav.archiving')}</ScrollLink>
                <ScrollLink to='project'>{t('app.nav.projects')}</ScrollLink>
                <LanguageSwitcher />
              </Box>
            )}
          </>
        </Box>
      </Box>

      {/* Background Image */}

      {/* Main Content */}
      <Box className={styles['content']}>
        <Intro scrollTo='intro' />
        <AboutMe scrollTo='AboutMe' />
        <Career scrollTo='Career' />
        <Skill scrollTo='skill' />
        <Archive scrollTo='Archive' />
        <Project scrollTo='project' />
        {/* <Career scrollTo="career" /> */}
      </Box>
    </Box>
  );
};

export default MainPage;
