import { IconDefinition } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { Box } from '@mui/material';
import { DefaultTFuncReturn } from 'i18next';

// Hooks
import { useBreakpoints } from '../../hooks/use-breakpoints.hook';

// Styles
import styles from './UserCard.module.scss';

type UserCardProps = {
  icon: IconDefinition;
  title: DefaultTFuncReturn | string;
  subtitle: DefaultTFuncReturn | string;
  more?: DefaultTFuncReturn | string;
};

export const UserCard = (props: UserCardProps) => {
  const { lgDown } = useBreakpoints();
  return (
    <Box className={styles['user-card']}>
      <FontAwesomeIcon
        className={styles['user-card-icon']}
        icon={props.icon}
        style={{ color: '#444444', fontSize: lgDown ? '20px' : '25px' }}
      />
      <Box
        className={styles['user-card-content']}
        sx={{ color: 'app.gray.dark' }}
      >
        <Box
          className={styles['user-card-content-title']}
          sx={{
            '::selection': {
              color: 'white',
              bgcolor: 'app.brown',
            },
          }}
        >
          {props.title}
        </Box>
        <Box
          className={styles['user-card-content-subtitle']}
          sx={{
            '::selection': {
              color: 'white',
              bgcolor: 'app.brown',
            },
          }}
        >
          {props.subtitle}
        </Box>
        {props.more && (
          <Box
            className={styles['user-card-content-subtitle']}
            sx={{
              '::selection': {
                color: 'white',
                bgcolor: 'app.brown',
              },
            }}
          >
            {props.more}
          </Box>
        )}
      </Box>
    </Box>
  );
};
